@app.route('/api/presence/historical', methods=['GET'])
def get_historical_presence():
    """Calculates who was in the room at a specific point in time."""
    timestamp_str = request.args.get('timestamp')
    if not timestamp_str:
        return jsonify({'error': 'Timestamp parameter is required'}), 400

    try:
        # Convert JS ISO string to a Python datetime object for comparison
        lookup_time = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
    except ValueError:
        return jsonify({'error': 'Invalid timestamp format'}), 400

    # This is a complex query to solve the "who was present" problem:
    # 1. Find the last action (ENTRY/EXIT) for each unique chip before the lookup time.
    subquery = db.session.query(
        AccessLog.chip_id,
        db.func.max(AccessLog.timestamp).label('last_timestamp')
    ).filter(
        AccessLog.timestamp <= lookup_time,
        AccessLog.result == 'GRANTED' # Only consider successful scans
    ).group_by(AccessLog.chip_id).subquery()

    # 2. Join the logs table with our subquery result to get the full details of that last action.
    final_query = db.session.query(AccessLog).join(
        subquery,
        db.and_(
            AccessLog.chip_id == subquery.c.chip_id,
            AccessLog.timestamp == subquery.c.last_timestamp
        )
    )

    # 3. From those last actions, only select the ones that were 'ENTRY'.
    present_users_logs = [log for log in final_query if log.direction == 'ENTRY']

    return jsonify([{'chip_id': p.chip_id, 'name': p.name_at_log, 'entry_time': p.timestamp.isoformat() + 'Z'} for p in present_users_logs])


