    chip=Chip.query.filter_by(chip_id=chip_id).first()
    if not chip: return 'NONE', 'DENIED (UNKNOWN)', 'Unknown'
    user_name=chip.name
    if not chip.is_allowed: return 'NONE', 'DENIED (BLOCKED)', user_name
    if chip.valid_until and chip.valid_until<datetime.utcnow(): return 'NONE', 'DENIED (EXPIRED)', user_name
    if chip.is_one_time: chip.is_allowed=False; db.session.commit()
    action='OPEN' if direction == 'ENTRY' else 'DOOR_OPENED'
    return action, 'GRANTED', user_name

